package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.net.Uri;import android.os.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;

/** One page per checkpoint. Native OCR resources never span more than the current page. */
final class OcrWork {
    static boolean modelsBusy(){TaskService service=TaskService.instance;if(service!=null&&service.current!=null)try(TaskStore db=new TaskStore(service)){StudyStore.Row job=db.job(service.current.id);if(job!=null&&(job.s("type").equals("ocr")||job.s("type").equals("model")))return true;}for(Activity active:WorkLeases.snapshot())if(active instanceof ReaderActivity&&((ReaderActivity)active).extras!=null&&((ReaderActivity)active).extras.ocr!=null)return true;return false;}
    static void choose(ReaderActivity a){int total=a.kind.equals("pdf")?a.pages:1;if(total<=0){PlusUi.toast(a,"Aguarde o documento abrir.");return;}LinearLayout form=PlusUi.column(a);EditText first=PlusUi.input(a,"Da página",""+(a.chrome.current()+1),7),last=PlusUi.input(a,"Até à página",""+(a.chrome.current()+1),7);first.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);last.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);form.addView(first);form.addView(last);ChoiceSpinner language=new ChoiceSpinner(a);language.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_item,new String[]{"Português","English"}));form.addView(language);new UiDialog.Builder(a).setTitle("Reconhecer várias páginas").setView(form).setPositiveButton("Preparar OCR",(d,w)->{try{int begin=Integer.parseInt(first.getText().toString()),end=Integer.parseInt(last.getText().toString());if(begin<1||end<begin||end>total)throw new IllegalArgumentException("Escolha um intervalo válido de páginas.");enqueue(a,begin-1,end-1,language.getSelectedItemPosition()==1?"eng":"por");}catch(Exception e){PlusUi.error(a,e);}}).setNegativeButton("Cancelar",null).show();}
    static void enqueue(ReaderActivity a,int first,int last,String language){PlusUi.run(a,()->{String id;try(TaskStore db=new TaskStore(a)){id=db.create("ocr","OCR · "+a.name,new JSONObject().put("uri",a.uri.toString()).put("name",a.name).put("mime",a.mime).put("language",language).put("material",a.getIntent().getLongExtra("study_material",0)));for(int part=first;part<=last;part++)db.add(id,part,a.uri.toString(),AppLanguage.text(a,"Página")+" "+(part+1),0,0);db.totals(id);}final String job=id;TaskService.launch(a,job);});}
    static File source(Context c,JSONObject data,TaskStore work,String id,TaskService.Control control)throws Exception{Uri uri=Uri.parse(data.getString("uri"));File managed=PrivateMaterial.file(c,uri);if(managed!=null)return managed;if(data.has("snapshot")){File staged=new File(data.getString("snapshot")).getCanonicalFile(),root=new File(c.getFilesDir(),"work-sources").getCanonicalFile();if(!DiskWalker.inside(root,staged)||!staged.isFile())throw new IOException("Fonte da tarefa indisponível. Abra novamente o documento.");return staged;}if("file".equals(uri.getScheme())){File file=new File(uri.getPath());if(!StorageAccess.allowed(c,file))throw new IOException("Sem acesso ao documento.");return file;}File dir=new File(c.getFilesDir(),"work-sources");dir.mkdirs();File target=new File(dir,id+"."+StudyFiles.extension(data.getString("name")));if(!target.isFile())try(InputStream in=c.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Fonte indisponível. Volte a abrir o documento.");File part=new File(target.getPath()+".part");if(part.exists())part.delete();StudyFiles.copy(in,target,DocumentBudget.available(dir,data.getString("name"),data.getString("mime")),control::cancelled);}data.put("snapshot",target.getPath());work.payload(id,data);return target;}
    static Bitmap image(Context c,File file)throws IOException{BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),options);if(options.outWidth<1||options.outHeight<1)throw new IOException("Imagem indisponível para OCR.");options.inSampleSize=ImageBudget.sample(options.outWidth,options.outHeight,PerformanceMode.light(c)?1700:2200);options.inJustDecodeBounds=false;Bitmap result=BitmapFactory.decodeFile(file.getPath(),options);if(result==null)throw new IOException("Imagem indisponível para OCR.");int[] fit=ImageBudget.fit(result.getWidth(),result.getHeight(),PerformanceMode.light(c)?1700:2200,PerformanceMode.light(c)?2000000:3500000);if(fit[0]!=result.getWidth()||fit[1]!=result.getHeight()){Bitmap scaled=Bitmap.createScaledBitmap(result,fit[0],fit[1],true);result.recycle();result=scaled;}return result;}
    static void run(Context c,StudyStore.Row job,TaskStore work,TaskService.Control control)throws Exception{String id=job.s("id");JSONObject data=new JSONObject(job.s("payload"));String language=data.optString("language","por");OcrEngine.install(c,language,control::cancelled,text->control.progress(text,work.count(id,"done"),work.count(id,null)));if(job.s("type").equals("model")){control.progress("Dados OCR disponíveis para uso offline.",1,1);return;}
        File source=source(c,data,work,id,control);String hash=data.optString("source_hash","");if(hash.isEmpty()){hash=StudyFiles.hash(source);data.put("source_hash",hash);work.payload(id,data);}Uri uri=Uri.parse(data.getString("uri"));String kind=MediaFormats.kind(data.getString("name"),data.getString("mime"));ParcelFileDescriptor fd=null;PdfRenderer pdf=null;try{if(kind.equals("pdf")){fd=ParcelFileDescriptor.open(source,ParcelFileDescriptor.MODE_READ_ONLY);pdf=new PdfRenderer(fd);}while(true){control.check();List<StudyStore.Row> pending=work.items(id,"pending",0,1);if(pending.isEmpty())break;StudyStore.Row item=pending.get(0);int part=(int)item.n("seq");Bitmap bitmap=null;OcrEngine engine=OcrEngine.create();control.interrupt=engine::cancel;try{if(data.optLong("material")>0)try(StudyStore db=new StudyStore(c)){if(db.get("materials",data.getLong("material"))==null)throw new IOException("O livro foi removido durante o OCR.");}if(pdf!=null){if(part<0||part>=pdf.getPageCount())throw new IOException("Página indisponível.");try(PdfRenderer.Page page=pdf.openPage(part)){int[] fit=ImageBudget.fit(page.getWidth(),page.getHeight(),PerformanceMode.light(c)?1900:2400,PerformanceMode.light(c)?2000000:3500000);bitmap=Bitmap.createBitmap(fit[0],fit[1],Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);}}else bitmap=image(c,source);
                    String text=engine.recognise(c,bitmap,language,control::cancelled,message->control.progress(message+" · "+(part+1),work.count(id,"done"),work.count(id,null)));control.check();OcrCache.save(c,uri.toString(),part,hash,text);work.item(id,part,StudyStore.values("state","done","message","Texto guardado · "+engine.confidence+"%"));
                }catch(InterruptedIOException e){throw e;}catch(LinkageError e){throw new IOException("OCR indisponível nesta arquitectura do aparelho.",e);}catch(Exception e){work.item(id,part,StudyStore.values("state","failed","message",e.getMessage()==null?"Não foi possível reconhecer":e.getMessage()));}finally{control.interrupt=null;if(bitmap!=null)bitmap.recycle();}long done=work.count(id,"done"),failed=work.count(id,"failed"),total=work.count(id,null);control.progress(done+" páginas reconhecidas · "+failed+" falhadas",done+failed,total);}
        }finally{if(pdf!=null)pdf.close();else if(fd!=null)fd.close();}if(work.count(id,"failed")>0)throw new IOException("Algumas páginas precisam de atenção. Pode retomar apenas as falhadas.");if(data.has("snapshot"))source.delete();LibraryIndex.enqueue(c);
    }
    static void model(Activity a,String language){PlusUi.run(a,()->{String id;try(TaskStore db=new TaskStore(a)){id=db.create("model","Dados de OCR",new JSONObject().put("language",language));}final String job=id;TaskService.launch(a,job);});}
    static void review(ReaderActivity a){String uri=a.uri.toString();PagedPicker.show(a,"Rever texto OCR",(query,offset,limit)->{List<PagedPicker.Entry> rows=new ArrayList<>();long total;try(PlusStore db=new PlusStore(a)){String[] args={uri,StudySchedule.like(query)};try(android.database.Cursor count=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM ocr_text WHERE uri=? AND value LIKE ? ESCAPE '\\'",args)){count.moveToFirst();total=count.getLong(0);}try(android.database.Cursor c=db.getReadableDatabase().rawQuery("SELECT segment,substr(value,1,100) FROM ocr_text WHERE uri=? AND value LIKE ? ESCAPE '\\' ORDER BY segment LIMIT ? OFFSET ?",new String[]{uri,args[1],""+limit,""+offset})){while(c.moveToNext())rows.add(new PagedPicker.Entry(c.getString(0),AppLanguage.text(a,"Página")+" "+(c.getInt(0)+1),c.getString(1)));}}return new PagedPicker.Page(rows,total);},entry->edit(a,uri,Integer.parseInt(entry.id)));}
    static void edit(ReaderActivity a,String uri,int part){PlusUi.run(a,()->{StudyStore.Row row=OcrCache.row(a,uri,part);if(row==null)throw new IOException("Texto OCR indisponível.");PlusUi.post(a,()->{EditText text=PlusUi.input(a,"Texto reconhecido",row.s("value"),1048576);text.setMinLines(8);text.setGravity(android.view.Gravity.TOP);new UiDialog.Builder(a).setTitle("Rever texto OCR").setView(text).setPositiveButton("Guardar",(d,w)->{String value=text.getText().toString();PlusUi.run(a,()->{File source=a.local();if(!StudyFiles.hash(source).equals(row.s("digest")))throw new IOException("O documento mudou. Reconheça novamente esta página.");OcrCache.save(a,uri,part,row.s("digest"),value);PlusUi.post(a,()->{if(a.tools!=null){a.tools.pdfTexts.remove(part);a.tools.navigate(part,0,true);}PlusUi.toast(a,"Texto OCR actualizado.");});});}).setNegativeButton("Cancelar",null).show();});});}
    private OcrWork(){}
}
